const allItems = $input.all();
const maxBatchSize = parseInt($env.DRIP_FEED_MAX_BATCH_SIZE || '2', 10) || 2;
const approvedBatch = [];

for (const item of allItems) {
  const row = item.json;
  const rowId = String(row['#'] || '').trim();
  const actor = String(row['Actor'] || '').trim();
  const movie = String(row['Movie (Year)'] || '').trim();
  const dialogue = String(row['Iconic Dialogue'] || '').trim();
  const angle = String(row['Poster Advertising Angle'] || '').trim();
  const status = String(row['Status'] || '').trim();
  const includeImage = String(row['Include Image?'] || 'Yes').trim();
  const linkedInPost = String(row['LinkedIn_Post'] || '').trim();
  const facebookPost = String(row['Facebook_Post'] || '').trim();
  const instagramPost = String(row['Instagram_Post'] || '').trim();
  const imageUrl = String(row['Image_URL'] || '').trim();
  const imageDescription = String(row['Image_Description'] || '').trim();
  const existingBufferIds = String(row['Buffer_Update_IDs'] || '').trim();

  if (rowId.length > 0 && status === 'Approved' && linkedInPost.length > 0 && facebookPost.length > 0) {
    const isImagePost = (includeImage.toLowerCase() !== 'no' && imageUrl.startsWith('http'));
    const targetChannels = isImagePost
      ? ['linkedin', 'facebook', 'instagram']
      : ['linkedin', 'facebook'];

    approvedBatch.push({
      json: {
        '#': rowId,
        Actor: actor,
        'Movie (Year)': movie,
        'Iconic Dialogue': dialogue,
        'Poster Advertising Angle': angle,
        'Include Image?': isImagePost ? 'Yes' : 'No',
        Status: 'Publishing',
        LinkedIn_Post: linkedInPost,
        Facebook_Post: facebookPost,
        Instagram_Post: instagramPost,
        Image_URL: isImagePost ? imageUrl : null,
        Image_Description: isImagePost ? imageDescription : `${movie} - ${dialogue}`,
        existing_buffer_ids: existingBufferIds,
        target_channels: targetChannels
      }
    });

    if (approvedBatch.length >= maxBatchSize) {
      break;
    }
  }
}

return approvedBatch;

const batchItems = $('03_Filter_Approved_Batch_Max_3').all();
const bufferToken = String($env.BUFFER_API_KEY || '').replace(/[<>/"'\s]/g, '');
const shareMode = (String($env.BUFFER_PUBLISH_IMMEDIATELY || 'true').toLowerCase() === 'true') ? 'shareNow' : 'addToQueue';

if (!bufferToken) {
  throw new Error('BUFFER_API_KEY is missing from environment variables.');
}

async function bufferGraphQL(helper, query, variables = {}) {
  const resp = await helper.httpRequest({
    method: 'POST',
    url: 'https://api.buffer.com',
    headers: {
      'Authorization': `Bearer ${bufferToken}`,
      'Content-Type': 'application/json'
    },
    body: { query, variables },
    json: true,
    timeout: 30000
  });
  if (resp.errors && resp.errors.length > 0) {
    throw new Error(resp.errors.map(e => e.message).join('; '));
  }
  return resp.data;
}

const orgData = await bufferGraphQL(
  this.helpers,
  `query GetOrgs { account { organizations { id name } } }`
);
const orgId = orgData?.account?.organizations?.[0]?.id;
if (!orgId) {
  throw new Error('No Buffer Organization found for this BUFFER_API_KEY.');
}

const chData = await bufferGraphQL(
  this.helpers,
  `query GetChannels($orgId: OrganizationId!) {
    channels(input: { organizationId: $orgId }) {
      id
      name
      service
      isDisconnected
    }
  }`,
  { orgId }
);

const channelList = chData?.channels || [];
const channelMap = {};
for (const ch of channelList) {
  const svc = String(ch.service || '').toLowerCase();
  if (!ch.isDisconnected && !channelMap[svc]) {
    channelMap[svc] = ch.id;
  }
}

const createPostMutation = `
  mutation CreatePost($input: CreatePostInput!) {
    createPost(input: $input) {
      __typename
      ... on PostActionSuccess {
        post {
          id
          status
        }
      }
      ... on MutationError {
        message
      }
    }
  }
`;

function getIstTimestamp() {
  return new Date().toLocaleString('en-IN', {
    timeZone: 'Asia/Kolkata',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  }) + ' IST';
}

const results = [];

for (const itemObj of batchItems) {
  const row = itemObj.json;
  const channelsToPublish = row.target_channels || ['linkedin', 'facebook', 'instagram'];
  const channelPayloads = {
    linkedin: row.LinkedIn_Post,
    facebook: row.Facebook_Post,
    instagram: row.Instagram_Post
  };

  const existingMap = {};
  if (row.existing_buffer_ids) {
    for (const part of row.existing_buffer_ids.split('|')) {
      const trimmed = part.trim();
      const [svcKey, postId] = trimmed.split(':');
      if (svcKey && postId && !postId.startsWith('buf_')) {
        existingMap[svcKey.trim().toLowerCase()] = postId.trim();
      }
    }
  }

  const updateIds = [];
  const errors = [];

  for (const serviceName of channelsToPublish) {
    if (existingMap[serviceName]) {
      updateIds.push(`${serviceName.toUpperCase()}:${existingMap[serviceName]}`);
      continue;
    }

    const channelId = channelMap[serviceName];
    if (!channelId) {
      errors.push(`${serviceName.toUpperCase()}: No connected ${serviceName} channel found in Buffer`);
      continue;
    }

    const postInput = {
      channelId: channelId,
      text: String(channelPayloads[serviceName] || '').trim(),
      schedulingType: 'automatic',
      mode: shareMode
    };

    if (serviceName === 'facebook') {
      postInput.metadata = { facebook: { type: 'post' } };
    } else if (serviceName === 'instagram') {
      postInput.metadata = { instagram: { type: 'post', shouldShareToFeed: true } };
    }

    if (row.Image_URL && row.Image_URL.startsWith('http')) {
      postInput.assets = [
        {
          image: {
            url: row.Image_URL,
            metadata: {
              altText: row.Image_Description || `Poster for ${row['Movie (Year)']}`
            }
          }
        }
      ];
    }

    try {
      const postData = await bufferGraphQL(this.helpers, createPostMutation, { input: postInput });
      const resultNode = postData?.createPost;
      if (resultNode?.__typename === 'PostActionSuccess' && resultNode?.post?.id) {
        updateIds.push(`${serviceName.toUpperCase()}:${resultNode.post.id}`);
      } else {
        const errMsg = resultNode?.message || JSON.stringify(resultNode);
        errors.push(`${serviceName.toUpperCase()}: ${errMsg}`);
      }
    } catch (err) {
      errors.push(`${serviceName.toUpperCase()}: ${err.message}`);
    }
  }

  const allSucceeded = (errors.length === 0 && updateIds.length === channelsToPublish.length);

  results.push({
    json: {
      '#': row['#'],
      final_status: allSucceeded ? 'Published' : 'Approved',
      buffer_update_ids: updateIds.join(' | '),
      error_message: errors.length > 0 ? errors.join(' | ') : '',
      actual_post_date: allSucceeded ? getIstTimestamp() : ''
    }
  });
}

return results;
